package dev.zomboid.isotacz;
public final class NativeInteraction {
 public static void open(Object mc,Object target){Object player=R.get(mc,"player");if(player==null||target==null)return;R.set(mc,"hitResult",target);boolean entity=R.call(target,"getType").toString().equals("ENTITY");R.set(mc,"crosshairPickEntity",entity?R.call(target,"getEntity"):null);R.call(mc,"startUseItem");}
 public static boolean gesture(boolean active,boolean crouching,boolean emptyMain,boolean emptyOff){return active&&crouching&&emptyMain&&emptyOff;}
 public static boolean mouse(long window,int button,int action,int modifiers,Object callback){Object mc=Bridge.mc(),player=R.get(mc,"player");if(player==null||button!=1||action!=1||R.get(mc,"screen")!=null||R.get(mc,"level")==null||R.get(mc,"gameMode")==null||window!=((Number)R.call(R.call(mc,"getWindow"),"getWindow")).longValue())return false;Object hands=R.type("net.minecraft.world.InteractionHand");if(!gesture(Bridge.active(),R.yes(R.call(player,"isShiftKeyDown")),R.yes(R.call(R.call(player,"getItemInHand",R.get(hands,"MAIN_HAND")),"isEmpty")),R.yes(R.call(R.call(player,"getItemInHand",R.get(hands,"OFF_HAND")),"isEmpty"))))return false;if(R.yes(R.call(R.type("dev.zomboid.isotacz.NativeActions"),"nativeInput")))return false;Object[] ray=(Object[])R.call(R.type("dev.zomboid.isotacz.CursorTarget"),"ray",mc);Object hit=R.call(R.type("dev.zomboid.isotacz.CursorTarget"),"pickRay",mc,ray[0],ray[1],true);if(hit==null)return false;String type=R.call(hit,"getType").toString();boolean range=type.equals("BLOCK")?R.yes(R.call(player,"canInteractWithBlock",R.call(hit,"getBlockPos"),0d)):type.equals("ENTITY")&&R.yes(R.call(player,"canInteractWithEntity",R.call(hit,"getEntity"),0d));if(!range||!R.yes(R.call(R.type("dev.zomboid.isotacz.CursorTarget"),"reachable",mc,R.call(player,"getEyePosition"),hit)))return false;R.call(R.type("dev.zomboid.isotacz.Bridge"),"setAim",false);open(mc,hit);R.set(R.type("dev.zomboid.isotacz.Bridge"),"mouseClaimed",true);R.call(callback,"cancel");return true;}
}
